style.css:
@-moz-document domain("depop.com") {
/* Content-hashed class names — hook only stable things: tags, ARIA roles,
     data-testid, module-name fragments, structure. Nearly every surface and text colour is
     hardcoded, so the :root token layer is not a usable single point of remap. */

  :root {
    color-scheme: dark;

    /* Resolves to #f3f3f3; only consumers are light SURFACES. The PDP nudge pill is
       re-established by class below, since `main div` outranks the token. */
    --surface-primary-weak: #1c2128;

    /* Primary ink (#262626), consumed by the typography classes (_body-*, _heading-*,
       _caption-*, _display_), which the site puts on ANY tag — the tag rules below miss a
       <div> carrying one. Keep unqualified so local rebinds win. */
    --text-primary-base: #c4cdd6;
  }

  /* ---- Base ---- */
  html,
  body {
    background-color: #14181d !important;
    color: #e6edf3 !important;
  }

  /* Soften every light border into a subtle dark line */
  * {
    border-color: #262c33 !important;
  }

  /* Typography: re-light dark hardcoded text */
  h1, h2, h3, h4, h5, h6 {
    color: #e6edf3 !important;
  }

  p,
  span,
  li,
  label,
  dd,
  dt,
  figcaption,
  blockquote,
  td,
  th {
    color: #c4cdd6 !important;
  }

  a {
    color: #c4cdd6 !important;
  }

  a:hover {
    color: #e6edf3 !important;
  }

  /* Header / nav — real sticky banner, re-establish opaque dark */
  header,
  [role="banner"],
  [data-testid="header"] {
    background-color: #0d1117 !important;
    border-color: #262c33 !important;
  }

  /* `header` is also a CONTENT tag inside <main>; only page chrome lives outside
     it. */
  main header {
    background-color: transparent !important;
  }

  header a,
  [role="banner"] a,
  [data-testid="header"] button {
    color: #e6edf3 !important;
  }

  header *,
  [role="banner"] * {
    color: #e6edf3 !important;
  }

  /* The nav's ONE accent item, painted by an inline `--textColor:#E20020` that the
     banner-text rule flattens. */
  [role="banner"] [style*="--textColor"],
  [role="banner"] [style*="--textColor"] * {
    color: #ff6b7d !important;
  }

  /* Sale's hover/open red pill (inline --hoverBg:#E20020); the extra specificity
     beats our generic [role="menuitem"]:hover grey. */
  [role="banner"] [style*="--hoverBg:#E20020"]:hover,
  [role="banner"] [style*="--hoverBg:#E20020"][aria-expanded="true"] {
    background-color: #d1304a !important;
  }

  [role="banner"] [style*="--hoverBg:#E20020"]:hover,
  [role="banner"] [style*="--hoverBg:#E20020"]:hover *,
  [role="banner"] [style*="--hoverBg:#E20020"][aria-expanded="true"],
  [role="banner"] [style*="--hoverBg:#E20020"][aria-expanded="true"] * {
    color: #ffffff !important;
  }

  /* The "you are here" icon (Likes / Bag), otherwise whited out by the banner-text
     rule. */
  [role="banner"] [class*="navigationLink--active"],
  [role="banner"] [class*="navigationLink--active"] *,
  a[class*="navigationLink--active"],
  a[class*="navigationLink--active"] * {
    color: #6ea8fe !important;
  }

  /* Skip links: clipped until :focus, then a solid #ffff47 slab. Keep the yellow,
     pin dark ink over the banner-text rule. */
  [class*="skipToLink"]:focus {
    color: #262626 !important;
    -webkit-text-fill-color: #262626 !important;
  }

  /* Category nav buttons and header inner containers sit on white pills */
  [role="banner"] button {
    background-color: transparent !important;
    color: #e6edf3 !important;
  }

  /* Nav containers carry white backgrounds outside <header> too */
  nav {
    background-color: transparent !important;
  }

  /* The active "thumb" paints a LIGHT gradient via background-image, invisible to a
     bg-COLOR reset. */
  nav span[class*="thumb"] {
    background-image: none !important;
    background-color: #30363d !important;
    border-color: #2d333b !important;
  }

  /* The app-download promo's light gradient is a background-IMAGE, surviving every
     bg-colour reset. Cover wrapper, card div and *Container boxes so it reads as one flat
     surface. The banner-scoped form is load-bearing:
     `[role="banner"] div[class*="Container"]` scores (0,2,1), above the (0,2,0) of a plain
     two-attribute descendant selector. */
  [class*="appDownloadBox"],
  [class*="appDownloadBox"] [class*="card"],
  [class*="appDownloadBox"] [class*="Container"],
  [role="banner"] [class*="appDownloadBox"] [class*="Container"] {
    background-image: none !important;
    background-color: #1c2128 !important;
  }

  /* The mega-menu renders OUTSIDE the banner and floats: keep it opaque dark. */
  [class*="hoverContainer"],
  [class*="hoverMenu"],
  header div[class*="Container"],
  [role="banner"] div[class*="Container"] {
    background-color: #0d1117 !important;
    border-color: #262c33 !important;
  }

  [class*="hoverContainer"] *,
  [class*="hoverMenu"] * {
    color: #c4cdd6 !important;
    background-color: transparent !important;
  }

  /* The autocomplete's "People" rows wrap avatar and text in *Container divs the
     site never paints; the banner Container fill above would box them inside the row's
     own hover band. Ties with that rule at (0,2,1), so it must stay below it. */
  [class*="searchSuggestionsContainer"] div[class*="Container"] {
    background-color: transparent !important;
  }

  /* Mega-menu "Featured" captions sit on a product photo, guaranteed by #262626 ink
     on an rgba(255,255,255,.7) plate the blanket menu rules re-light and strip. Restore
     both, scoped to an image container so plain menu links keep the light colour. */
  [class*="featuredImageContainer"] [class*="descriptionText"] {
    color: #262626 !important;
    -webkit-text-fill-color: #262626 !important;
    background-color: rgba(255, 255, 255, 0.7) !important;
  }

  /* A light row fill is these links' ONLY hover affordance, and the blanket
     menu-descendant transparent rule above is !important; the pseudo-class lifts this over
     it. */
  [class*="categoryListLink"]:hover,
  [class*="categoryListFooter"]:hover {
    background-color: #262c33 !important;
  }

  /* A mega-menu entry can be accented with an inline `color:red`, which our
     !important rules beat. The attribute selector tests the AUTHORED string and the site
     ships both spellings. */
  [class*="hoverContainer"] [style*="color:red"],
  [class*="hoverContainer"] [style*="color: red"] {
    color: #ff6b7d !important;
  }

  /* Global search bar + dropdown */
  input,
  textarea,
  select {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  input::placeholder,
  textarea::placeholder {
    color: #8b949e !important;
    opacity: 1 !important;
  }

  /* The visible "On sale" box is an appearance:none input's ::before — a
     pseudo-element surface. */
  input[type="checkbox"]::before {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  /* Checked is natively #2960af and disabled #d7d7d7; one flat fill would leave
     the three states apart only by the tick glyph. */
  input[type="checkbox"]:checked::before {
    background-color: #2960af !important;
    border-color: #2960af !important;
  }

  input[type="checkbox"]:disabled::before {
    background-color: #30363d !important;
    border-color: #30363d !important;
  }

  /* Quiz radios' empty/full reading inverts on dark. Must stay ABOVE the
     radioIndicatorError rule below, which overrides only the border and would lose the tie
     on equal specificity. */
  [class*="radioIndicator"] {
    background-color: #1c2128 !important;
    border-color: #4a525b !important;
  }

  [class*="radioIndicatorSelected"] {
    border-color: #e6edf3 !important;
  }

  [class*="radioIndicatorSelected"]::after {
    background-color: #e6edf3 !important;
  }

  [data-testid="searchBar__input"] {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
  }

  [data-testid="searchBar__input"]::placeholder {
    color: #8b949e !important;
    opacity: 1 !important;
  }

  /* "CLEAR" is a filled pill, flattened to bare text by the
     `[role="banner"] button` transparent reset. */
  [class*="searchBarButtons"] [class*="clearButton"] {
    background-color: #4a525b !important;
    color: #ffffff !important;
  }

  [class*="searchBarButtons"] [class*="clearButton"]:hover {
    background-color: #5c656f !important;
  }

  /* The submit arrow keeps the UA default `border-style: outset` with a TRANSPARENT
     border-color, which the blanket `*` reset makes opaque — `outset` then derives a bright
     bevel from it. */
  [class*="searchBarButtons"] [class*="submitButton"] {
    border-color: transparent !important;
  }

  /* Hover/focus fills the disc indigo; our !important banner-button reset outranks
     the site's plain :hover. */
  [class*="searchBarButtons"] [class*="submitButton"]:hover,
  [class*="searchBarButtons"] [class*="submitButton"]:focus {
    background-color: #3d37bd !important;
    color: #ffffff !important;
  }

  /* The highlighted row fills #3d37bd with a WHITE category suffix; our
     categorySuggestionText accent below is !important and would leave blue-on-blue. Qualify
     with `li`: `searchSuggestionsContainer` contains the substring `searchSuggestion`, so a
     bare attribute selector makes the whole list :hover whenever one row is. */
  li[class*="searchSuggestion"]:hover [class*="categorySuggestionText"],
  li[class*="searchSuggestion"]:focus [class*="categorySuggestionText"],
  li[class*="searchSuggestion"]:active [class*="categorySuggestionText"] {
    color: #ffffff !important;
  }

  /* Search autocomplete / suggestion dropdown — keep opaque */
  [role="listbox"],
  [role="menu"],
  [role="dialog"],
  [role="combobox"] ul,
  ul[id*="listbox"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  [role="option"],
  [role="menuitem"] {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  [role="option"]:hover,
  [role="menuitem"]:hover {
    background-color: #262c33 !important;
    color: #e6edf3 !important;
  }

  /* The modal's title bar is a position:sticky <span> filled #fff, portaled outside
     <main>, which [role="dialog"] above does not reach. Desktop uses the fill-less
     variant. */
  [class*="modalHeader__header"] {
    background-color: #1c2128 !important;
  }

  /* Main content area + filter / sort bar.
     The white containers carry no stable hook, and inside <main> nothing has an intentional
     surface colour — blank them all and re-skin the controls. */
  main,
  main div,
  main section,
  [role="main"],
  [role="main"] div {
    background-color: transparent !important;
  }

  /* Promo bands paint a LIGHT gradient via background-image, reused for every
     full-width promo <section> under its own hash — match the tag: no <section> inside
     <main> carries artwork of its own. */
  main section,
  [class*="homepageHero"],
  [class*="HomepageHero"],
  [class*="heroBanner"],
  [class*="promoBanner"],
  [class*="quizEntryPoint"] {
    background-image: none !important;
    background-color: transparent !important;
  }

  /* The hero is A/B'd through `data-variant`: `red` fills the band #e20020, `grey`
     #262626, the unattributed legacy hero the pale gradient the reset above targets.
     #a81021 still clears 7.5:1 for the white copy pinned on it. */
  [class*="homepageHero"][data-variant="red"] {
    background-color: #a81021 !important;
  }

  [class*="homepageHero"][data-variant="red"] h1,
  [class*="homepageHero"][data-variant="red"] h2,
  [class*="homepageHero"][data-variant="red"] p {
    color: #ffffff !important;
  }

  /* On that band the trust signals take poppy-700 plates with white glyphs, not the
     plate + #43484d glyph the generic rules below restore. */
  [class*="homepageHero"][data-variant="red"] [class*="trustSignalContainer"] > div,
  [class*="homepageHero"][data-variant="red"] [class*="trustSignalContainer"] > a {
    background-color: #8d0e1c !important;
  }

  [class*="homepageHero"][data-variant="red"] [class*="trustSignal"] svg path {
    fill: #ffffff !important;
  }

  /* Inverted CTA: white pill, --text-accent-base ink. Pin the hover too — the site
     takes it from --surface-primary-weak, which we remap dark. */
  [class*="homepageHero"][data-variant="red"] [class*="heroCta"] button {
    background-color: #e6edf3 !important;
    color: #a81021 !important;
  }

  [class*="homepageHero"][data-variant="red"] [class*="heroCta"] button:hover {
    background-color: #ffffff !important;
  }

  /* Both attributed variants paint the Buy/Sell track poppy-700 under a WHITE thumb;
     the legacy hero has no data-variant. */
  [class*="homepageHero"][data-variant] nav {
    background-color: #8d0e1c !important;
  }

  [class*="homepageHero"][data-variant] nav span[class*="thumb"] {
    background-color: #e6edf3 !important;
    border-color: #e6edf3 !important;
  }

  [class*="homepageHero"][data-variant] nav a p {
    color: #ffffff !important;
  }

  [class*="homepageHero"][data-variant] nav a[aria-current="page"] p {
    color: #a81021 !important;
  }

  /* The Top Seller hero's SATURATED brand band, toned so the restored white copy
     clears 6:1. Two stops only: the site layers a radial bloom the old userstyles.org
     parser cannot take. `section[class*="__hero"]` alone also matches geometry-only
     `__hero` sections on /gb/sell/ and /partners/depop-affiliates/; the
     `main > div[class*="__page"] >` prefix isolates this one. */
  main > div[class*="__page"] > section[class*="__hero"] {
    background-image: linear-gradient(#a81021 0%, #a8420c 100%) !important;
  }

  /* Its copy is natively pure white BECAUSE it sits on that band; our generic
     greys drop to 3.8:1 on the orange end. */
  main > div[class*="__page"] > section[class*="__hero"] h1,
  main > div[class*="__page"] > section[class*="__hero"] h2,
  main > div[class*="__page"] > section[class*="__hero"] p,
  main > div[class*="__page"] > section[class*="__hero"] span,
  main > div[class*="__page"] > section[class*="__hero"] strong {
    color: #ffffff !important;
  }

  /* A white-pill-on-colour CTA with no "outl" class, which the solid rule below
     would paint the band's own red. Must stay BELOW the white-ink rule above, which also
     matches the label span. */
  main > div[class*="__page"] > section[class*="__hero"] [class*="buttonWrapper"] {
    background-color: #e6edf3 !important;
    border-color: #e6edf3 !important;
  }

  main > div[class*="__page"] > section[class*="__hero"] [class*="buttonWrapper"]:hover {
    background-color: #ffffff !important;
  }

  main > div[class*="__page"] > section[class*="__hero"] [class*="buttonWrapper"],
  main > div[class*="__page"] > section[class*="__hero"] [class*="buttonWrapper"] * {
    color: #262626 !important;
  }

  /* The class PAIR isolates the closing marquee band: `__banner` alone also matches
     the slideshow's bannerButton pills and bannerImage photos. */
  main div[class*="__banner"][class*="__container"] {
    background-color: #ac1700 !important;
  }

  /* `stepCard` tiles carry the light gradient as a background-IMAGE on a <div>
     inside an <li>, which neither the `main div` bg-COLOUR reset nor the `main section`
     gradient rule reaches. */
  [class*="stepCard"] {
    background-image: none !important;
    background-color: #1c2128 !important;
  }

  /* Shop-by-price tiles carry the light gradient in an inline `--background`, as a
     background-IMAGE. Hook BOTH the module fragment and the inline property: a CSS-modules
     reshuffle breaks one, a data change the other. `--background:` with the colon must not
     match the swatches' `--background-color:` / `--background-image:`. */
  [class*="tileWrapper"] [class*="background"],
  main [style*="--background:"] {
    background-image: none !important;
    background-color: #1c2128 !important;
  }

  button {
    color: #e6edf3 !important;
  }

  /* Carousel arrows are white discs with a currentColor chevron; they are <button>s,
     so the `main div` reset never reaches them while the `button` rule above lights the
     chevron. */
  button[class*="navButton"] {
    background-color: #1c2128 !important;
    border-color: #4a525b !important;
  }

  button[class*="navButton"]:hover {
    background-color: #262c33 !important;
  }

  /* The slide's copy panel is a plain <div> inside <main>, erased by the `main div`
     reset. Scope through slidesWrapper: contentWrapper is reused for unpainted layout
     wrappers elsewhere. */
  [class*="slidesWrapper"] [class*="contentWrapper"] {
    background-color: #262c33 !important;
  }

  /* The 8px indicators are <div>s wiped by the same reset; they overlay the photo,
     not our chrome, so light values are the faithful restore. `indicatorDot` does not match
     `activeIndicatorDot`, but the current dot carries both, so the active rule must stay
     below. */
  [class*="indicatorDot"] {
    background-color: #8b949e !important;
  }

  /* ...but NOT the row: `indicatorDotsContainer` contains the substring
     `indicatorDot`, which would fill the wrapper as one solid bar. */
  [class*="indicatorDotsContainer"] {
    background-color: transparent !important;
  }

  [class*="activeIndicatorDot"] {
    background-color: #ffffff !important;
  }

  /* "Shop now" is the design system's `outline` variant, which on this component
     means a SOLID WHITE pill with border-width:0 — no border to fall back on if the generic
     outline rule below darkens it. */
  [class*="slidesWrapper"] button[class*="bannerButton"] {
    background-color: #e6edf3 !important;
    border-color: #e6edf3 !important;
  }

  [class*="slidesWrapper"] button[class*="bannerButton"]:hover {
    background-color: #ffffff !important;
  }

  [class*="slidesWrapper"] button[class*="bannerButton"],
  [class*="slidesWrapper"] button[class*="bannerButton"] * {
    color: #262626 !important;
  }

  /* Filter / sort trigger pills and dropdown buttons.
     NOT [aria-haspopup]: Depop puts aria-haspopup="dialog" on plain text and icon controls
     (card hearts, follower counts, message icon, rating stars). */
  [aria-expanded] {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* Filter dropdown panels / popovers */
  [class*="dropdown"],
  [class*="Dropdown"],
  [class*="popover"],
  [class*="Popover"],
  [class*="menu"],
  [class*="Menu"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  /* The panel rule above beats the site's own light hover, leaving no
     feedback. */
  [class*="FilterDropdownOption"]:hover,
  [class*="searchFilterCheckbox"]:hover {
    background-color: #262c33 !important;
  }

  /* Section headings are <div>s inked #747474 — 3.4:1 on the dark panel — and no
     tag rule reaches a <div>. */
  [class*="brandFilterDropdownHeading"] {
    color: #8b949e !important;
  }

  /* Group headers paint a light hover fill, leaving the pale label
     light-on-light. */
  [class*="collapsibleRow"]:hover {
    background-color: #262c33 !important;
  }

  /* Chips hover to a near-white fill; nothing of ours paints the <label>, so it
     would survive under our light chip text. */
  label[class*="sizeButton"]:hover {
    background-color: #262c33 !important;
  }

  /* Size chips encode "selected" as a dark fill only. The state lives on an
     opacity:0 checkbox read through `:has()`, which sanitization strips, and the checkbox
     FOLLOWS the label text, so no sibling combinator reaches it. Promote the checkbox
     itself into the marker: absolutely positioned with the label as offsetParent. Keep it
     click-transparent — the label already forwards the toggle. */
  label[class*="sizeButton"] input[type="checkbox"]:checked {
    appearance: none !important;
    -webkit-appearance: none !important;
    opacity: 1 !important;
    box-sizing: border-box !important;
    top: 0 !important;
    left: 0 !important;
    width: 100% !important;
    height: 100% !important;
    margin: 0 !important;
    background-color: transparent !important;
    border: 2px solid #e6edf3 !important;
    border-radius: 4px !important;
    pointer-events: none !important;
  }

  /* The MOBILE PDP's position:fixed action bar is #fff inside <main>, so the
     `main div` reset makes it see-through. Both selectors resolve to the same node — the
     inline `bottom` pins the bar. */
  [class*="productInfo"] > div > div[class*="container"],
  [class*="productInfo"] div[style*="bottom"] {
    background-color: #14181d !important;
  }

  /* The mobile "Filter" drawer is a position:fixed, full-viewport panel painted
     #fff inside <main>. */
  [class*="filtersContainer"] {
    background-color: #14181d !important;
  }

  [class*="filtersContainer"] [class*="footer"] {
    background-color: #14181d !important;
    color: #8b949e !important;
  }

  /* Placeholder tiles under a white message card, both erased by the transparent
     reset. Keep the card a step lighter and opaque so the tiles do not run behind its
     text. */
  [class*="emptySlide"] {
    background-color: #1c2128 !important;
  }

  [class*="emptyMessage"] {
    background-color: #262c33 !important;
  }

  /* Swatch dots take their fill from an inline `--background-color` /
     `--background-image` the `main div` reset wipes; ring each so a near-black swatch stays
     visible. colourCircle is the PDP's copy of the same pattern. */
  main [class*="colourFilterColourSpot"],
  main [class*="colourCircle"] {
    background-color: var(--background-color) !important;
    background-image: var(--background-image) !important;
    border: 1px solid #4a525b !important;
  }

  /* Match the CONTROLS only: the bare forms also match their plain <div> wrappers
     (popularPillsContainer, pillsContainer, activeFiltersContainer) and the <p> and <svg>
     inside every trigger. */
  main button[class*="pill"],
  main button[class*="Pill"],
  main a[class*="pill"],
  main a[class*="Pill"],
  [class*="badgePill"],
  button[class*="chip"],
  button[class*="Chip"],
  button[class*="activeFilter"],
  button[class*="FilterTrigger"],
  label[class*="FilterTrigger"],
  button[class*="FilterButton"] {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  button[class*="activeFilter"] * {
    color: #c4cdd6 !important;
  }

  /* badgePill's glyph is #262626 — invisible once the pill above turns dark. */
  [class*="badgeIcon"] {
    color: #c4cdd6 !important;
  }

  main button[class*="pill"]:hover,
  main button[class*="Pill"]:hover,
  main a[class*="pill"]:hover,
  main a[class*="Pill"]:hover,
  button[class*="chip"]:hover,
  button[class*="Chip"]:hover,
  button[class*="activeFilter"]:hover,
  button[class*="FilterTrigger"]:hover,
  label[class*="FilterTrigger"]:hover,
  button[class*="FilterButton"]:hover {
    background-color: #262c33 !important;
    color: #e6edf3 !important;
  }

  /* The applied pill is the INVERTED one, but both carry `pill`, so the fill above
     ties with it. Must stay BELOW the base pill rules: rest and hover win only by order. */
  main button[class*="pillActive"] {
    background-color: #e6edf3 !important;
    color: #14181d !important;
    border-color: #e6edf3 !important;
  }

  main button[class*="pillActive"]:hover {
    background-color: #ffffff !important;
    color: #14181d !important;
  }

  /* Letter chips are <a>s the `main div` reset never reaches.
     `brandGroupsNavLinkActive` contains the substring `brandGroupsNavLink`, so the inverted
     rules must stay below the rest state. */
  [class*="brandGroupsNavLink"] {
    background-color: #1c2128 !important;
    border-color: #4a525b !important;
  }

  [class*="brandGroupsNavLink"] p {
    color: #c4cdd6 !important;
  }

  [class*="brandGroupsNavLink"]:hover,
  [class*="brandGroupsNavLink"]:focus,
  [class*="brandGroupsNavLinkActive"] {
    background-color: #e6edf3 !important;
  }

  [class*="brandGroupsNavLink"]:hover p,
  [class*="brandGroupsNavLink"]:focus p,
  [class*="brandGroupsNavLinkActive"] p {
    color: #14181d !important;
  }

  /* The sitemap tabs are bare <li>s `main div` never reaches. Across every
     logged-out page type `li[class*="__tab"]` matches this strip alone; the profile's
     Shop/Likes tabs are tabsWrapper/tabHighlight. */
  li[class*="__tab"] {
    background-color: #1c2128 !important;
  }

  /* Must stay BELOW: the active tab carries both classes and ties on specificity. */
  li[class*="activeTab"] {
    background-color: #e6edf3 !important;
  }

  li[class*="activeTab"] a {
    color: #14181d !important;
  }

  /* The login "or" row draws its arms as ::before/::after borders, which the `*`
     border reset cannot reach. */
  hr {
    background-color: #262c33 !important;
    border-color: #262c33 !important;
  }

  /* The active-tab indicator is an <hr> the divider rule above would leave the exact
     colour of the rule it sits on. */
  hr[class*="tabHighlight"] {
    background-color: #e6edf3 !important;
    border-color: #e6edf3 !important;
  }

  /* ...and its strip is a position:sticky #fff bar inside <main>, made see-through
     by the `main div` reset when scrolled. */
  [class*="tabsWrapper"] {
    background-color: #14181d !important;
  }

  [class*="divider"]::before,
  [class*="divider"]::after {
    border-color: #262c33 !important;
  }

  /* A bare bullet TEXT glyph with no surface of its own — a background fill draws a
     slab over it. */
  [class*="dotDivider"] {
    background-color: transparent !important;
  }

  /* Product result cards / grid */
  a[href*="/products/"] {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  /* Price text on cards + PDP — keep bright/legible */
  a[href*="/products/"] p,
  a[href*="/products/"] span {
    color: #e6edf3 !important;
  }

  /* The site mutes the struck-through price against a strong current one; both land
     on the same ink here. */
  [class*="discountedFullPrice"],
  [class*="originalPrice"] {
    color: #8b949e !important;
  }

  /* The site's one yellow signal; the card-price rule directly above outranks a
     bare class selector. */
  [class*="soldText"],
  a[href*="/products/"] [class*="soldText"] {
    color: #ffda0a !important;
    -webkit-text-fill-color: #ffda0a !important;
  }

  /* Product detail page (PDP) */
  /* Image gallery stage + thumbnails: keep wrappers dark */
  [data-testid="mobile"],
  [data-testid="desktop"],
  [class*="Image"],
  [class*="image"],
  [class*="gallery"],
  [class*="Gallery"],
  [class*="carousel"],
  [class*="Carousel"] {
    background-color: transparent !important;
  }

  /* The white disc is the whole reason these overlay controls read as buttons, and
     it is a plain <div> the `main div` reset erases. Ring it with `outline`, not
     box-shadow: the site's :focus-within paints a #ffda0a box-shadow ring an !important
     box-shadow would erase, while our shorthand keeps outline-width/-color. */
  [class*="buttonInteractionWrapper"] {
    background-color: #1c2128 !important;
    outline: 1px solid #4a525b !important;
  }

  /* Same shape one layer over, for the MOBILE gallery's arrows. Must stay BELOW the
     `[class*="carousel"]` transparent reset — the class contains that substring and the two
     tie on specificity. */
  [class*="carouselActionContainer"] {
    background-color: #1c2128 !important;
    outline: 1px solid #4a525b !important;
  }

  /* Nudge pills filled from --surface-primary-weak, which `main div` outranks. Hook
     the testid: the component ships one wrapper per nudge kind. */
  [data-testid*="NudgeWrapper"] {
    background-color: #1c2128 !important;
  }

  /* Skeletons paint a LIGHT animated gradient as a background-IMAGE, surviving every
     bg-COLOUR reset. The placeholderShimmer keyframes animate background-position, left
     intact. */
  [class*="shimmerStyles"],
  [class*="Skeleton"],
  [class*="skeleton"] {
    background-image: linear-gradient(90deg, #1c2128 0px, #2d333b 20%, #1c2128 40%, #1c2128) !important;
    background-color: #1c2128 !important;
  }

  /* Price */
  [data-testid="productPrimaryAttributes"],
  [data-testid="productPrimaryAttributes"] * {
    color: #e6edf3 !important;
  }

  /* The "show more" link paints a scroll-fade behind itself via ::after — a
     background-IMAGE gradient to #fff. */
  [class*="showMoreButton"]::after {
    background-image: linear-gradient(90deg, rgba(20, 24, 29, 0), rgb(20, 24, 29) 30%) !important;
  }

  /* NO surface rule for [data-testid^="segment--"] or
     [data-testid="productCard__sizeAttr"]: both mark plain transparent text nodes, not
     pills, so an elevated fill paints page-wide grey bands down the PDP. */

  /* The round disc IS the initials child; [data-testid="avatar"] is a bare wrapper
     the site never paints (a photo avatar mounts an <img>). */
  [data-testid="avatar"] {
    background-color: transparent !important;
  }

  [data-testid="avatar__initials"] {
    background-color: #4a525b !important;
  }

  /* The review count sits in a <div class="_caption-sm-bold"> the p/span rules don't
     reach; keep the link free of any button surface. */
  [class*="feedbackButton"] {
    background-color: transparent !important;
    border-color: transparent !important;
  }

  [class*="feedbackButton"] * {
    color: #c4cdd6 !important;
  }

  /* The star row draws the SAME glyph for both states, encoding the score purely in
     colour, which the blanket rule above flattens. Must stay BELOW the feedbackButton rule:
     the bare-class forms tie with it and win only by order. The path needs its own `fill` —
     that rule lands a DIRECT `color` on it. */
  [class*="filledStar"],
  [class*="filledStar"] svg {
    color: #e6edf3 !important;
  }

  [class*="filledStar"] svg path {
    fill: #e6edf3 !important;
  }

  [class*="emptyStar"],
  [class*="emptyStar"] svg {
    color: #4a525b !important;
  }

  [class*="emptyStar"] svg path {
    fill: #4a525b !important;
  }

  /* The site's only blue affordance, flattened into body copy by the generic
     link/text rules. */
  [class*="seeMoreText"],
  [class*="seeMoreText"] *,
  [class*="buttonLinkWrapperVariant"],
  [class*="buttonLinkWrapperVariant"] *,
  [class*="buttonLinkTextVariant"],
  [class*="buttonLinkTextVariant"] * {
    color: #6ea8fe !important;
  }

  /* The one hover cue is a lighter blue; the rule above is !important and would
     pin both states to the same tone. */
  [class*="buttonLinkWrapperVariant"]:hover,
  [class*="buttonLinkWrapperVariant"]:hover * {
    color: #9ec5fe !important;
  }

  /* Like / save / interaction buttons (icon + count) */
  [data-testid^="productInteraction__"],
  [data-testid^="productInteraction__"] * {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  /* These SVG paths are fill/stroke "currentColor" over a hardcoded dark `color` —
     their colour is the single point of repair. */
  [class*="bannerContainer"] svg,
  [class*="shippingIcon"],
  footer [class*="socialLink"] svg,
  [data-testid="footerV2"] [class*="socialLink"] svg {
    color: #c4cdd6 !important;
  }

  /* The TikTok badge carries a literal fill="black" ATTRIBUTE, not currentColor. The
     row appears in the footer AND the MOBILE nav drawer, so scope to the class, not the
     footer. */
  [class*="socialLink"] path[fill="black"] {
    fill: #c4cdd6 !important;
  }

  /* These glyphs are painted with `fill`, which beats `color`, so the icon rules
     above cannot reach them. */
  [class*="trustSignal"] svg,
  [class*="trustSignal"] svg path {
    fill: #8b949e !important;
  }

  /* All THREE signals share one rgba(255,255,255,0.3) plate; the tappable one is an
     <a> and the others <div>s, so match on the parent. `trustSignal` alone would also catch
     this container and its <p>s. */
  [class*="trustSignalContainer"] > div,
  [class*="trustSignalContainer"] > a {
    background-color: #1c2128 !important;
  }

  /* Buttons — the design system renders as <button>/<span>/<a> carrying a
     "buttonWrapper" class with hardcoded light fills; the primary submit/CTA takes the
     Depop red. */
  /* Outline / secondary pills → elevated dark surface */
  [class*="buttonWrapper"][class*="outl"] {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  [class*="buttonWrapper"][class*="outl"]:hover {
    background-color: #262c33 !important;
  }

  /* Solid / primary pills carry Depop's high-emphasis fill → the brand red,
     toned */
  [class*="buttonWrapper"]:not([class*="outl"]),
  button[type="submit"] {
    background-color: #d1304a !important;
    color: #ffffff !important;
    border-color: transparent !important;
  }

  [class*="buttonWrapper"]:not([class*="outl"]):hover,
  button[type="submit"]:hover {
    background-color: #f1556a !important;
  }

  [class*="buttonWrapper"]:not([class*="outl"]) * {
    color: #ffffff !important;
  }

  [class*="buttonWrapper"][class*="outl"] * {
    color: #e6edf3 !important;
  }

  /* Header "Sign up" / "Log in" reuse the button component with a white override and
     no "outl" class, so the solid rule above would paint both the "Sell now" red. */
  [class*="buttonWrapper"][class*="textButton--"],
  [class*="buttonWrapper"][class*="textButton--"] * {
    background-color: transparent !important;
    color: #e6edf3 !important;
  }

  [class*="buttonWrapper"][class*="textButton--login"] {
    border-color: transparent !important;
  }

  [class*="buttonWrapper"][class*="textButton--signup"] {
    border-color: #4a525b !important;
  }

  [class*="buttonWrapper"][class*="textButton--"]:hover {
    background-color: #262c33 !important;
  }

  /* Apple's brand-mandated BLACK pill. Its fill sits on the wrapper carrying the pill
     radius, inside <main>, so the `main div` reset erases it; ring it with an inset
     shadow. */
  [class*="ssoLoginOptionsContainer"] [class*="wrapper"] {
    background-color: #000000 !important;
    box-shadow: inset 0 0 0 1px #3a4149 !important;
  }

  /* /magic-link mounts the same button under a DIFFERENT wrapper module, so paint the
     button itself; it exactly fills the wrapper, so the 40px radius here reproduces the pill
     without a layout change. */
  [class*="appleButton"] {
    background-color: #000000 !important;
    border-radius: 40px !important;
    box-shadow: inset 0 0 0 1px #3a4149 !important;
  }

  [class*="appleButton"],
  [class*="appleButton"] * {
    color: #ffffff !important;
  }

  /* The SEMANTIC solid variants and the disabled state carry no "outl" class, so the
     solid rule above would swallow them into the primary red. */
  [class*="buttonWrapper"][class*="colorStyles--green"] {
    background-color: #2f7d24 !important;
    border-color: #2f7d24 !important;
  }

  [class*="buttonWrapper"][class*="colorStyles--blue"] {
    background-color: #2960af !important;
    border-color: #2960af !important;
  }

  [class*="buttonWrapper"][class*="colorStyles--facebook"] {
    background-color: #4a66a0 !important;
    border-color: #4a66a0 !important;
  }

  [class*="buttonWrapper"][class*="colorStyles--yellow"] {
    background-color: #ffda0a !important;
    border-color: #ffda0a !important;
    color: #262626 !important;
  }

  [class*="buttonWrapper"][class*="colorStyles--yellow"] * {
    color: #262626 !important;
  }

  [class*="buttonWrapper"]:disabled {
    background-color: #30363d !important;
    border-color: #30363d !important;
    color: #8b949e !important;
  }

  [class*="buttonWrapper"]:disabled * {
    color: #8b949e !important;
  }

  /* Must stay BELOW the solid and outline :hover rules: `:disabled:hover` ties
     with both at (0,3,0), so only order keeps a hovered disabled pill from
     taking the CTA fill under its muted ink. */
  [class*="buttonWrapper"]:disabled:hover {
    background-color: #30363d !important;
    border-color: #30363d !important;
  }

  /* Outline variants tint only their label, which the outline-text rule above
     flattens. */
  [class*="buttonWrapper"][class*="outline--green"] * {
    color: #56b04a !important;
  }

  [class*="buttonWrapper"][class*="outline--blue"] * {
    color: #6ea8fe !important;
  }

  [class*="buttonWrapper"][class*="outline--yellow"] * {
    color: #ffda0a !important;
  }

  /* A SECOND button component: `_button_<hash>_` plus
     `_primary_/_secondary_/_tertiary_`, no buttonWrapper, so nothing above reaches it.
     `_button_` with both underscores does not match `_buttonWrapper_`; the `button` tag
     keeps the label rule off the `_button_<hash>_` TYPOGRAPHY class the old component puts
     on its labels. */
  button[class*="_button_"] [class*="_label_"] {
    color: inherit !important;
  }

  button[class*="_button_"][class*="_primary_"] {
    color: #ffffff !important;
  }

  /* Its base rule reserves the outline variant's ring as `2px solid transparent`,
     which the blanket `*` border-color reset turns opaque on every filled pill. Only the
     secondary variant paints one. */
  button[class*="_button_"] {
    border-color: transparent !important;
  }

  button[class*="_button_"][class*="_secondary_"] {
    border-color: #4a525b !important;
  }

  /* The design system's text ACTIONS are an indigo (#3d37bd) the generic
     a/button/span rules flatten into body copy. sellerWebsite is the bio's site link (the
     other blue). Qualify ctaButton with `button`: a third module reuses the name for a
     geometry-only modal CTA that must keep its solid-button ink. */
  [class*="resetAllButton"],
  [class*="resetAllButton"] *,
  button[class*="ctaButton"],
  button[class*="ctaButton"] *,
  [class*="dismissModalButton"],
  [class*="deleteText"],
  [class*="categorySuggestionText"],
  [class*="seeSimilarItemsText"],
  [class*="toastLink"],
  [class*="tipsLink"],
  [class*="todoButton"],
  [class*="ctaWrapper"] a,
  [class*="sellerWebsite"] {
    color: #6ea8fe !important;
  }

  /* Depop "Sale" / red accents — tone the raw #e20020 for dark */
  [style*="226, 0, 32"],
  [class*="sale"],
  [class*="Sale"] {
    color: #ff6b7d !important;
  }

  /* #e20020 is also Depop's ERROR colour, which the blanket p/span/label rule would
     grey into body copy. */
  [class*="errorText"],
  [class*="errorMessage"],
  [class*="ErrorMessage"],
  [class*="errorMessage"] *,
  [class*="lightTextError"],
  [class*="zeroLeftWarning"],
  [class*="offerAlertText"],
  [class*="offersToReview"],
  [class*="rejectedOfferTitle"] {
    color: #ff6b7d !important;
  }

  /* ...and the field's matching red outline, erased by the blanket `*` border
     reset. */
  [class*="priceFilterInputError"],
  [class*="inputContainerError"],
  [class*="descriptionErrorBorder"],
  [class*="radioIndicatorError"] {
    border-color: #ff6b7d !important;
    outline-color: #ff6b7d !important;
  }

  /* Bio and description links are brand red, which the blanket `a` rule greys into
     the surrounding copy. */
  [class*="shopBio"] a,
  [class*="description"] a {
    color: #ff6b7d !important;
  }

  /* Icon AND label are green; the icon keeps its own colour, the blanket `p` rule
     greys the LABEL. */
  [class*="shippingMessage"] {
    color: #56b04a !important;
  }

  /* The badge keeps its solid red fill, but the generic span/p rule would drop its
     label to ~3.3:1 on that red. */
  [class*="discountLabel"],
  [class*="discountLabel"] * {
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
  }

  /* Portaled outside <main>; the 8px track keeps a hardcoded light fill. The red
     progress fill stays Depop red. */
  [class*="progressionBarContainer"] {
    background-color: #30363d !important;
  }

  /* Captions laid over the photo, painted pure #ffffff so they survive a bright
     frame. The same component backs the home section's inline tiles and the modal's later
     steps. */
  [class*="labelOverlay"],
  [class*="labelOverlay"] p,
  [class*="labelOverlay"] span {
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
  }

  /* The unselected tile's rgba(255,255,255,.5) veil LIGHTENS on dark — de-emphasise
     downward at the site's own alpha. On the homepage's inline tiles the veil is a <div>
     inside <main>: this selector's (0,1,0) outranks the transparent reset's (0,0,2). Only
     outline-COLOR — the site paints a #ffda0a focus outline on the same element through
     outline-width/offset. */
  [class*="fadeOverlay"] {
    background-color: rgba(20, 24, 29, 0.5) !important;
  }

  [class*="labelSelected"] {
    outline-color: #e6edf3 !important;
  }

  /* Footer */
  footer,
  [data-testid="footerV2"],
  footer div,
  [data-testid="footerV2"] div {
    background-color: #0d1117 !important;
    border-color: #262c33 !important;
  }

  footer a,
  [data-testid="footerV2"] a {
    color: #c4cdd6 !important;
  }

  footer a:hover,
  [data-testid="footerV2"] a:hover {
    color: #e6edf3 !important;
  }

  /* SVG icons that were black, made readable on dark */
  svg[fill="#000000"],
  svg[fill="#000"],
  svg[fill="black"] {
    fill: #e6edf3 !important;
  }

  /* `domain("depop.com")` also covers news.depop.com, a separate styled-components
     frontend. Its wordmark's letter paths carry NO fill, taking the SVG default black — the
     rules above match only a literal black fill ATTRIBUTE. The badge beside it pins its
     colours inline, which our !important would steal, so restore the white "d"
     explicitly. */
  [class*="StyledLogoLink"] svg path {
    fill: #e6edf3 !important;
  }

  [class*="StyledLogoLink"] svg circle + path {
    fill: #ffffff !important;
  }

  /* The current-section link is the raw brand red, 3.8:1 on our header bar; the
     `> ul > li >` chain keeps the sub-menu's own aria-current entry, which the site leaves
     uncoloured, out of it. */
  [class*="StyledNav-"] > ul > li > a[aria-current="page"] {
    color: #ff6b7d !important;
  }

  /* The photo bands paint their light plate with a full-size ::before AND
     ::after on the section, not on any box. */
  [class*="StyledImagePreview"]::before,
  [class*="StyledImagePreview"]::after {
    background-color: #1c2128 !important;
  }

  /* State is carried by SIZE (14px current vs 10px), separated only by a
     styled-components hash suffix — one fill serves both. */
  [class*="StyledDotIndication"] {
    background-color: #c4cdd6 !important;
  }
}
